SELECT ?word ?wordLabel WHERE {
  ?word wdt:P31 wd:Q11030.
  ?word wdt:P407 wd:Q1860.
  ?word rdfs:label ?wordLabel.
  FILTER(LANG(?wordLabel) = "en")
  BIND(STRLEN(?wordLabel) AS ?len)
  {
    SELECT (MAX(?length) AS ?maxLen) WHERE {
      ?w wdt:P31 wd:Q11030; wdt:P407 wd:Q1860; rdfs:label ?l.
      FILTER(LANG(?l) = "en")
      BIND(STRLEN(?l) AS ?length)
    }
  }
  FILTER(?len = ?maxLen)
}
ORDER BY ?wordLabel

