  SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en". }
}

SELECT ?continentLabel ?riverLabel ?length WHERE {
  {
    SELECT ?continent (MAX(?length) AS ?maxLen) WHERE {
      ?river wdt:P31 wd:Q4022;
             wdt:P2043 ?length;
             wdt:P30 ?continent.
      ?continent wdt:P31 wd:Q5107.
    }
    GROUP BY ?continent
  }
  ?river wdt:P31 wd:Q4022;
         wdt:P2043 ?maxLen;
         wdt:P30 ?continent.
  BIND(?maxLen AS ?length)
  SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en". }
}
ORDER BY DESC(?length)

