SELECT ?city ?cityLabel ?citySitelinks ?country ?countryLabel ?countrySitelinks WHERE {
  ?city wdt:P31/wdt:P279* wd:Q515 .
  ?city wdt:P17 ?country .

  {
    SELECT ?city (COUNT(?sitelink) AS ?citySitelinks) WHERE {
      ?sitelink schema:about ?city .
      ?sitelink schema:isPartOf ?site .
      FILTER(CONTAINS(STR(?site), "wikipedia.org"))
    } GROUP BY ?city
  }

  {
    SELECT ?country (COUNT(?sitelink) AS ?countrySitelinks) WHERE {
      ?sitelink schema:about ?country .
      ?sitelink schema:isPartOf ?site .
      FILTER(CONTAINS(STR(?site), "wikipedia.org"))
    } GROUP BY ?country
  }

  FILTER(?citySitelinks > ?countrySitelinks)

  SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en". }
}

