  {
    SELECT ?player (SUM(?goals) AS ?totalGoals) WHERE {
      ?match wdt:P361 wd:Q170645.
      ?match p:P1027 ?statement.
      ?statement ps:P1027 ?player.
      ?statement pq:P3301 ?goals.
    }
    GROUP BY ?player
    ORDER BY DESC(?totalGoals)
  }
  SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en". }
}
GROUP BY ?player ?playerLabel ?goals
ORDER BY DESC(?goals)

