SELECT ?decade (COUNT(?person) AS ?count)
WHERE {
  ?person wdt:P31 wd:Q5 ;
          wdt:P19 ?birthPlace ;
          wdt:P20 ?deathPlace ;
          wdt:P569 ?birthDate .

  ?birthPlace wdt:P17 wd:Q213 .
  ?deathPlace wdt:P17 wd:Q183 .

