  FILTER(LANG(?numberLabel) = "en")
}
ORDER BY ?numberLabel

SELECT ?city ?cityLabel (COUNT(DISTINCT ?river) AS ?riverCount) WHERE {
  ?city wdt:P31/wdt:P279* wd:Q515 .
  ?city wdt:P206 ?river .
  ?river wdt:P31 wd:Q4022 .
  SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en". }
}
GROUP BY ?city ?cityLabel
HAVING (COUNT(DISTINCT ?river) > 1)
ORDER BY DESC(?riverCount)

SELECT ?item ?itemLabel ?coords ?typeLabel WHERE {
  ?item wdt:P31/wdt:P279* wd:Q6256 ;
        wdt:P131 wd:Q25 ;
        wdt:P625 ?coords ;
        wdt:P31 ?type .
  FILTER(?type IN (wd:Q167634, wd:Q33506, wd:Q206389, wd:Q19088))
  SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en". }
}

SELECT ?person ?personLabel (COUNT(DISTINCT ?country) AS ?countryCount) WHERE {
  ?person wdt:P31 wd:Q5.
  ?person p:P166 ?awardStatement.
  ?awardStatement ps:P166 ?award.
  ?award wdt:P17 ?country.
  ?country wdt:P31 wd:Q6256.
  ?awardStatement pq:P1027 ?recipient.
  FILTER(?person = ?recipient || !EXISTS { ?awardStatement pq:P1027 ?any })

  {
    ?award wdt:P279* wd:Q185535.
  } UNION {
    ?award wdt:P31/wdt:P279* wd:Q185535.
  }

  GROUP BY ?person ?personLabel
  HAVING (COUNT(DISTINCT ?country) >= 2)
}
SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en". }

SELECT ?occupationLabel (COUNT(?person) AS ?count) WHERE {
