SELECT ?country ?countryLabel ?capital ?capitalLabel WHERE {
  ?country wdt:P31 wd:Q6256.
  ?country wdt:P36 ?capital.

  ?country rdfs:label ?countryLabel. FILTER(LANG(?countryLabel) = "en")
  ?capital rdfs:label ?capitalLabel. FILTER(LANG(?capitalLabel) = "en")

  BIND(LCASE(REPLACE(?countryLabel, "[^a-z]", "", "i")) AS ?cName)
  BIND(LCASE(REPLACE(?capitalLabel, "[^a-z]", "", "i")) AS ?capName)

  FILTER(STRLEN(?capName) > 0)

  # Check if every character in the capital name exists in the country name
  # We use a subquery approach or filter logic to verify character counts
  FILTER NOT EXISTS {
    SELECT ?char WHERE {
      BIND(STRDT(?capName, xsd:string) AS ?str)
      # Split capital into characters
      SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
      # This is a simplified check; for full character count validation, 
      # we ensure every unique char in capital is present in country
    }
  }

  # Logic: For every character in capital, it must be present in country
  FILTER(
    REPLACE(?capName, CONCAT("[", ?cName, "]"), "") = ""
  )
}

