SELECT ?language ?languageLabel (COUNT(?lexeme) AS ?count) WHERE {
  ?lexeme wikibase:lexicalCategory ?category .
  ?lexeme dct:language ?language .
  FILTER NOT EXISTS { ?lexeme ?p ?o . FILTER(?p != wikibase:lemma && ?p != dct:language && ?p != wikibase:lexicalCategory && ?p != rdf:type) }
  FILTER NOT EXISTS { ?lexeme ontolex:sense ?sense }
  SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en". }
}
GROUP BY ?language ?languageLabel
HAVING (?count < 10)

SELECT ?institution ?institutionLabel WHERE {
  {
    SELECT (COUNT(DISTINCT ?conference) AS ?totalCount) WHERE {
      ?conference wdt:P31 wd:Q2020153 ;
                  wdt:P1441 wd:Q106574667 .
    }
  }
  {
    SELECT ?institution (COUNT(DISTINCT ?conference) AS ?contributionCount) WHERE {
      ?conference wdt:P31 wd:Q2020153 ;
                  wdt:P1441 wd:Q106574667 ;
                  wdt:P170 ?institution .
    }
    GROUP BY ?institution
  }
  FILTER(?contributionCount = ?totalCount)
  SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en". }
}

