SELECT ?composer ?composerLabel ?tonality ?tonalityLabel (COUNT(?work) AS ?count)
WHERE {
  ?work wdt:P86 ?composer .
  ?work wdt:P826 ?tonality .
  SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en". }
}
GROUP BY ?composer ?composerLabel ?tonality ?tonalityLabel
HAVING (?count = (
  SELECT MAX(?c)
  WHERE {
    SELECT (COUNT(?w) AS ?c)
    WHERE {
      ?w wdt:P86 ?composer .
      ?w wdt:P826 ?t .
    }
    GROUP BY ?composer ?t
  }
))
ORDER BY ?composerLabel

