SELECT ?number WHERE {
  BIND(1 AS ?start)
  BIND(2000 AS ?end)
  SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en". }
  {
    SELECT (STR(?n) AS ?number) WHERE {
      BIND(IRI(CONCAT("http://www.wikidata.org/entity/Q", STR(?n))) AS ?item)
      FILTER(?n >= 1 && ?n <= 2000)
    }
  }
}
ORDER BY ?n

