SELECT ?person1 ?person1Label ?place1 ?person2 ?person2Label ?place2 WHERE {
  ?person1 wdt:P31 wd:Q5;
           wdt:P1542 ?birthEvent1.
  ?birthEvent1 wdt:P31 wd:Q754006.
  ?person2 wdt:P31 wd:Q5;
           wdt:P1542 ?birthEvent2.
  ?birthEvent2 wdt:P31 wd:Q754006.

  FILTER(?person1 < ?person2)

  ?person1 wdt:P19 ?place1.
  ?person2 wdt:P19 ?place2.

  FILTER(?place1 != ?place2)

  SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en". }
}

