SELECT ?place ?placeLabel ?article ?articleLabel WHERE {
  SERVICE wikibase:around {
    ?place wdt:P625 ?location .
    bd:serviceParam wikibase:center "Point(2.3522 48.8566)"^^geo:wktLiteral .
    bd:serviceParam wikibase:radius "5" .
  }
  ?article schema:about ?place ;
           schema:isPartOf <https://en.wikipedia.org/> .
  SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en". }
}

SELECT ?presidentLabel ?ageAtInauguration WHERE {
  ?president wdt:P39 wd:Q11696.
  ?president p:P39 ?statement.
  ?statement ps:P39 wd:Q11696.
  ?statement pq:P580 ?start_date.
  ?president wdt:P569 ?birth_date.

  BIND(year(?start_date) - year(?birth_date) - IF(month(?start_date) < month(?birth_date) || (month(?start_date) = month(?birth_date) && day(?start_date) < day(?birth_date)), 1, 0) AS ?ageAtInauguration)

  SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en". }
}
ORDER BY ?start_date

SELECT ?award ?awardLabel ?date WHERE {
  wd:Q10187 wdt:P166 ?awardStatement.
  ?awardStatement ps:P166 ?award.
  OPTIONAL { ?awardStatement pq:P585 ?date. }
