SELECT ?person ?personLabel ?start_date ?end_date (xsd:integer(year(?end_date) - year(?start_date)) AS ?duration) WHERE {
  ?person wdt:P39 wd:Q142;
          p:P39 ?statement.
  ?statement ps:P39 wd:Q142;
             pq:P580 ?start_date.
  OPTIONAL { ?statement pq:P582 ?end_date. }
  BIND(IF(BOUND(?end_date), ?end_date, NOW()) AS ?effective_end)
  FILTER(xsd:integer(year(?effective_end) - year(?start_date)) >= 5)
  SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en". }
}
ORDER BY DESC(?duration)

