  }
  ?painting wdt:P31 wd:Q3305213.
  ?painting wdt:P17 ?country.
  ?painting wikibase:sitelinks ?maxSitelinks.
  SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en". }
}
ORDER BY DESC(?maxSitelinks)

SELECT ?person ?personLabel WHERE {
  ?person wdt:P31 wd:Q5;
          wdt:P27 wd:Q258;
          wdt:P21 wd:Q6581072.
  ?sitelink schema:about ?person;
            schema:isPartOf <https://en.wikipedia.org/>.
  FILTER NOT EXISTS {
    ?sitelinkQ schema:about ?person;
               schema:isPartOf <https://en.wikiquote.org/>.
  }
  SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en". }
}

SELECT ?item ?itemLabel ?coords WHERE {
  ?item wdt:P31 wd:Q1146646.
  ?item wdt:P180 wd:Q132366.
  ?item wdt:P625 ?coords.
  SERVICE wikibase:around {
    ?item wdt:P625 ?coords.
    bd:serviceParam wikibase:center "Point(0 0)"^^geo:wktLiteral.
    bd:serviceParam wikibase:radius "5" .
  }
  SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en". }
}

SELECT ?movie ?movieLabel ?youtubeID WHERE {
  ?movie wdt:P31 wd:Q11424.
  ?movie wdt:P1651 ?youtubeID.
  SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en". }
}

SELECT ?moon ?moonLabel ?namesake ?namesakeLabel WHERE {
  ?moon wdt:P31 wd:Q2537;
        wdt:P361 ?planet.
  ?planet wdt:P31 wd:Q35347.
  ?moon wdt:P138 ?namesake.
  SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en". }
}

SELECT ?monument ?monumentLabel ?person ?personLabel WHERE {
  ?monument wdt:P31/wdt:P279* wd:Q575663.
  ?monument wdt:P138 ?person.
  FILTER NOT EXISTS {
    ?monument ?p ?o.
    FILTER(?p != wdt:P31 && ?p != wdt:P279 && ?p != wdt:P138 && ?p != wdt:P17 && ?p != wdt:P131 && ?p != wdt:P18 && ?p != wdt:P373)
    FILTER(?o != ?person)
  }
  SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en". }
}

SELECT ?language ?languageLabel WHERE {
  wd:Q55 rdfs:label ?label .
  wd:Q55 p:P2936 ?statement .
  ?statement ps:P2936 ?language .
  SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en". }
}

SELECT DISTINCT ?party ?partyLabel WHERE {
  ?member p:P39 ?statement .
  ?statement ps:P39 wd:Q16956366 ;
             pq:P2715 wd:Q17006666 .
  ?statement pq:P4100 ?party .
  SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en". }
}

SELECT ?languageLabel ?followerCount ?date WHERE {
  ?language wdt:P31 wd:Q9143.
  ?language p:P8687 ?statement.
  ?statement ps:P8687 ?followerCount.
  ?statement pq:P585 ?date.
  SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en". }
}
ORDER BY ?languageLabel DESC(?date)

SELECT DISTINCT ?language ?languageLabel ?code WHERE {
  ?lemma wikibase:lemma ?lemmaText ;
         dct:language ?language .
  ?language wdt:P218 ?code .
  SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en". }
}

SELECT DISTINCT ?typeLabel WHERE {
  ?item wdt:P195 wd:Q693481.
  ?item wdt:P31 ?type.
  SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en". }
}

SELECT ?item ?itemLabel ?diameter ?inception WHERE {
  ?item wdt:P31 wd:Q193567.
  ?item wdt:P2386 ?diameter.
  ?item wdt:P571 ?inception.
  BIND(YEAR(?inception) AS ?year)
  SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en". }
}
ORDER BY ?inception

SELECT ?letterLabel (COUNT(?writingSystem) AS ?count) WHERE {
  ?writingSystem wdt:P31 wd:Q820696.
  ?writingSystem wdt:P282 ?script.
  ?script wdt:P279* wd:Q8134.
  ?writingSystem wdt:P282 ?letter.
  ?letter wdt:P31 wd:Q107344.
  SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en". }
}
GROUP BY ?letterLabel
ORDER BY DESC(?count)

SELECT ?descendant ?descendantLabel WHERE {
  ?descendant wdt:P40* wd:Q193505.
  SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en". }
}

SELECT ?firstName (COUNT(?person) AS ?count) WHERE {
  ?person wdt:P39 wd:Q1939586 ;
          wdt:P27 wd:Q142 .
  FILTER NOT EXISTS { ?person wdt:P570 ?deathDate }
  ?person wdt:P735 ?firstNameEntity .
  ?firstNameEntity rdfs:label ?firstName .
  FILTER(LANG(?firstName) = "fr")
}
GROUP BY ?firstName
ORDER BY DESC(?count)

SELECT ?work ?workLabel ?date WHERE {
  ?work wdt:P50 wd:Q9061.
  ?work wdt:P577 ?date.
  SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en". }
}

SELECT ?date_type ?date WHERE {
  wd:Q7126 wdt:P569 ?birth_date .
  wd:Q7126 wdt:P570 ?death_date .
  VALUES (?date_type ?date) {
    ("date of birth" ?birth_date)
    ("date of death" ?death_date)
  }
}

SELECT ?property ?propertyLabel WHERE {
  ?property wdt:P31 wd:Q1860 ;
            wikibase:propertyType ?type .
  SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en". }
}

SELECT ?language ?languageLabel (COUNT(?film) AS ?count)
WHERE {
  ?film wdt:P31 wd:Q11424.
  ?sitelink schema:about ?film ;
            schema:isPartOf ?wiki .
  ?wiki wikibase:wikiGroup "wikipedia" .
  ?language wdt:P424 ?langCode .
  FILTER(STRSTARTS(STR(?wiki), CONCAT("https://", ?langCode, ".wikipedia.org/")))
  SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en". }
}
GROUP BY ?language ?languageLabel
ORDER BY DESC(?count)
LIMIT 10

SELECT ?item ?itemLabel WHERE {
  ?item schema:about wd:Q214665;
        schema:isPartOf <https://en.wikipedia.org/>.
  SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en". }
}

SELECT ?city ?cityLabel ?population WHERE {
  ?city wdt:P31 wd:Q515 ;
        wdt:P17 wd:Q183 ;
        wdt:P1082 ?population .
  FILTER(?population > 50000)
  SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en". }
}

SELECT ?country ?countryLabel ?isoCode ?flag ?fertilityRate WHERE {
  ?country wdt:P31 wd:Q6256.
  ?country wdt:P297 ?isoCode.
  ?country wdt:P41 ?flag.
  ?country wdt:P4801 ?fertilityRate.
  SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en". }
}

SELECT ?typeLabel (COUNT(?work) AS ?count) WHERE {
  ?work wdt:P31/wdt:P279* wd:Q7725634.
  ?work wdt:P31 ?type.
  SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en". }
}
GROUP BY ?typeLabel
ORDER BY DESC(?count)

SELECT ?decade (SAMPLE(?placeLabel) AS ?place) (COUNT(?person) AS ?count)
WHERE {
  ?person wdt:P166 wd:Q7191.
  ?person wdt:P19 ?place.
  ?person wdt:P569 ?birthDate.
  BIND(STR(FLOOR(YEAR(?birthDate) / 10) * 10) AS ?decade)
  SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en". }
}
GROUP BY ?decade ?place
ORDER BY ?decade ?count
